package ru.folio.notes;

import java.awt.*;
import java.awt.geom.*;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.ArrayList;
import javax.imageio.ImageIO;

public final class LaserTests {
    static int assertions;
    static void check(boolean ok,String text){if(!ok)throw new AssertionError(text);assertions++;}
    static class Probe implements LaserEffect.Sink {
        int segments,spots,rings,bands;float radius,opacity,x,y,total;boolean crossedGap;float firstX=Float.NaN,lastX;final ArrayList<Float> trailAlpha=new ArrayList<>();
        public void beginTrail(float width,int color,float alpha){bands++;trailAlpha.add(alpha);check(width>0&&Float.isFinite(width),"positive finite width");check(alpha>=0&&alpha<=1,"bounded trace opacity");}
        public void segment(float ax,float ay,float bx,float by){segments++;if(Float.isNaN(firstX))firstX=ax;lastX=bx;if(ax<500&&bx>500)crossedGap=true;check(Float.isFinite(ax)&&Float.isFinite(ay)&&Float.isFinite(bx)&&Float.isFinite(by),"finite segment");}
        public void endTrail(){}
        public void spot(float x,float y,float r,int color,float alpha){spots++;this.x=x;this.y=y;radius=r;opacity=alpha;check(r>0&&Float.isFinite(r)&&alpha>=0&&alpha<=1,"bounded laser spot");}
        public void ring(float x,float y,float r,float w,int color,float alpha){rings++;check(alpha>=0&&alpha<=1&&r>0&&w>0,"bounded contact ring");}
    }
    static Probe probe(LaserEffect laser,long now){Probe p=new Probe();laser.render(now,1,p);return p;}
    static void dot(){LaserEffect laser=new LaserEffect();check(!laser.trail,"point is default");laser.down(20,40,1000);for(int i=1;i<=200;i++)laser.move(20+i,40,1000+i);Probe p=probe(laser,1200);check(p.segments==0&&laser.pointCount()==0,"moving dot never creates a line");check(p.x==220&&p.y==40&&p.spots==1,"point exactly follows tip");laser.release(1200);float a=probe(laser,1250).opacity,b=probe(laser,1360).opacity;check(a>b&&b>0,"release fades continuously");check(!laser.active(1421)&&!laser.needsFrame(1421),"dot animation stops after release");laser.down(10,10,1500);laser.clear();check(!laser.active(1501)&&!laser.touching,"cancellation removes all light");System.out.println("PASS default point follows tip, draws no line, fades and cancels");}
    static void pulse(){LaserEffect laser=new LaserEffect();laser.down(50,60,1000);float a=probe(laser,1100).radius,b=probe(laser,1600).radius;check(Math.abs(a-b)>.05,"stationary point pulses");laser.pulse=false;check(Math.abs(probe(laser,1700).radius-probe(laser,1900).radius)<.001,"pulse can be disabled");check(!laser.needsFrame(1900),"static stationary pointer avoids idle frame loop");laser.release(1950);check(laser.needsFrame(1960),"fade still animates with pulse off");laser.clear();laser.hover(40,80,2000);Probe p=probe(laser,2100);check(p.spots==1&&p.segments==0,"hover uses a glowing point");laser.leave(2200);check(!laser.active(2421),"hover exit fades and stops");System.out.println("PASS pulse, local pulse preference, hover and idle cleanup");}
    static void trail(){LaserEffect laser=new LaserEffect();laser.mode(true);laser.down(20,40,1000);laser.move(100,40,1100);laser.release(1110);laser.down(800,100,1200);laser.move(900,100,1300);laser.release(1310);Probe p=probe(laser,1350);check(p.segments>0&&!p.crossedGap,"separate gestures never join");check(p.bands==2,"bounded render batches");for(long now=1360;now<2200;now+=17){p=probe(laser,now);check(p.bands<=LaserEffect.BANDS,"bounded fading work");}check(!laser.active(2210)&&laser.pointCount()==0,"all trails expire independently");laser.down(20,30,3000);laser.move(30,40,3100);laser.mode(false);check(!laser.active(3101)&&laser.pointCount()==0,"switching to point clears former trail");System.out.println("PASS independently fading traces, gesture separation and mode change");}
    static void heldTrail(){LaserEffect laser=new LaserEffect();laser.mode(true);laser.pulse=false;laser.down(20,40,1000);laser.move(100,40,1100);Probe initial=probe(laser,1200),held=probe(laser,121200);check(held.segments==initial.segments&&held.firstX==20&&held.lastX==100,"old start and full path remain during long contact");check(held.trailAlpha.get(0)==1,"contact retains full brightness");check(!laser.needsFrame(121200),"stationary retained trace does not need idle frames");for(int i=0;i<500;i++)laser.move(100,40,121200+i);check(laser.pointCount()==2,"stationary input does not fill path buffer");laser.release(122000);Probe early=probe(laser,122100),late=probe(laser,122600);check(early.segments==1&&late.segments==1&&early.firstX==late.firstX,"whole path fades together after lift");check(early.trailAlpha.get(0)>late.trailAlpha.get(0)&&late.trailAlpha.get(0)>0,"release fade has continuous opacity");laser.hover(300,400,122650);check(probe(laser,122901).segments==0,"hover cannot prolong a released trace");laser.clear();laser.down(20,40,130000);laser.move(100,40,130010);laser.release(130020);laser.down(800,100,130100);laser.move(900,100,130110);Probe both=probe(laser,130500);check(both.bands==2&&both.trailAlpha.get(0)<1&&both.trailAlpha.get(1)==1&&!both.crossedGap,"new contact cannot revive old trace or connect it");Probe newest=probe(laser,130921);check(newest.bands==1&&newest.firstX==800,"old trace expires while new contact remains");laser.clear();for(int i=0;i<100;i++){laser.down(i*10,0,140000+i);laser.move(i*10+5,0,140000+i);laser.release(140000+i);}check(probe(laser,140100).bands<=LaserEffect.BANDS,"many overlapping releases have bounded draw batches");System.out.println("PASS held full trace, long stationary contact, whole-gesture fade, independent release clocks and hover");}
    static void capacity(){LaserEffect laser=new LaserEffect();laser.mode(true);laser.down(10,10,1000);for(int i=1;i<=10000;i++){laser.move(10+i,20+(float)Math.sin(i*.1),1000+i);check(laser.pointCount()<=LaserEffect.CAPACITY,"history stays bounded during long drag");}Probe p=probe(laser,11000);check(p.segments<LaserEffect.CAPACITY+LaserEffect.BANDS,"sparse batching scales with bounded history");check(p.firstX==10&&p.lastX==10010,"compaction retains beginning and end of a long gesture");check(p.trailAlpha.get(0)==1,"compacted trace remains fully visible");laser.clear();check(!laser.active(11001),"long drag clears immediately");laser.down(10,10,20000);for(int i=1;i<=20000;i++)laser.move(10+Math.min(i,10000),10+Math.max(0,i-10000),20000+i);boolean corner=false;for(int i=0;i<laser.count;i++)if(laser.xs[i]==10010&&laser.ys[i]==10)corner=true;check(corner,"compaction retains sharp corner of long trace");check(laser.xs[0]==10&&laser.ys[0]==10,"long corner trace retains origin");check(laser.xs[laser.count-1]==10010&&laser.ys[laser.count-1]==10010,"long corner trace retains endpoint");laser.clear();System.out.println("PASS bounded memory, retained endpoints and render work for long continuous input");}
    static final class Painter implements LaserEffect.Sink {
        Graphics2D g;Path2D path=new Path2D.Float();float width,alpha,lastX,lastY;int color;boolean any;
        Painter(Graphics2D g){this.g=g;g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);}
        void color(int rgb,float alpha){g.setPaint(new Color((rgb>>16)&255,(rgb>>8)&255,rgb&255));g.setComposite(AlphaComposite.SrcOver.derive(Math.max(0,Math.min(1,alpha))));}
        public void beginTrail(float width,int color,float alpha){path.reset();this.width=width;this.color=color;this.alpha=alpha;any=false;}
        public void segment(float ax,float ay,float bx,float by){if(!any||Math.abs(ax-lastX)+Math.abs(ay-lastY)>.002f)path.moveTo(ax,ay);path.lineTo(bx,by);lastX=bx;lastY=by;any=true;}
        public void endTrail(){if(!any)return;float[] widths={6,2.7f,1,.32f},opacity={.055f,.22f,.92f,.87f};for(int i=0;i<4;i++){color(i==3?0xffffefef:color,alpha*opacity[i]);g.setStroke(new BasicStroke(width*widths[i],i<2?BasicStroke.CAP_ROUND:BasicStroke.CAP_BUTT,BasicStroke.JOIN_ROUND));g.draw(path);}}
        public void spot(float x,float y,float r,int rgb,float alpha){Color base=new Color(rgb);g.setComposite(AlphaComposite.SrcOver.derive(alpha));g.setPaint(new RadialGradientPaint(new Point2D.Float(x,y),r*5,new float[]{0,.25f,.6f,1},new Color[]{new Color(base.getRed(),base.getGreen(),base.getBlue(),217),new Color(base.getRed(),base.getGreen(),base.getBlue(),101),new Color(base.getRed(),base.getGreen(),base.getBlue(),24),new Color(base.getRed(),base.getGreen(),base.getBlue(),0)}));g.fill(new Ellipse2D.Float(x-r*5,y-r*5,r*10,r*10));color(rgb,alpha);g.fill(new Ellipse2D.Float(x-r,y-r,r*2,r*2));color(0xfffff7f7,alpha);g.fill(new Ellipse2D.Float(x-r*.46f,y-r*.46f,r*.92f,r*.92f));}
        public void ring(float x,float y,float r,float width,int color,float alpha){color(color,alpha);g.setStroke(new BasicStroke(width));g.draw(new Ellipse2D.Float(x-r,y-r,r*2,r*2));}
    }
    static void simulate(LaserEffect effect,long phase){effect.clear();effect.diameter=8;effect.down(40,130,200);for(long t=216;t<=Math.min(phase,1700);t+=16){float f=(t-200)/1500f;effect.move(40+280*f,130+(float)Math.sin(f*Math.PI*3)*42,t);}if(phase>1700)effect.release(1700);}
    static BufferedImage frame(long phase){BufferedImage image=new BufferedImage(800,420,BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setColor(new Color(0x17191f));g.fillRect(0,0,800,420);g.setColor(new Color(0xf5f2e9));g.fillRoundRect(18,80,374,318,22,22);g.setColor(new Color(0x212630));g.fillRoundRect(408,80,374,318,22,22);g.setColor(new Color(0xdde0df));for(int y=105;y<390;y+=26)g.drawLine(18,y,392,y);g.setColor(new Color(0x323945));for(int y=105;y<390;y+=26)g.drawLine(408,y,782,y);g.setFont(new Font("SansSerif",Font.BOLD,21));g.setColor(new Color(0xf4f2ed));g.drawString("Лазерная точка",25,39);g.drawString("Светящийся след",416,39);g.setFont(new Font("SansSerif",Font.PLAIN,13));g.setColor(new Color(0x9ca2ad));g.drawString("Указатель без линии",25,62);g.drawString("Сохраняется до отрыва",416,62);
        for(int mode=0;mode<2;mode++){Graphics2D layer=(Graphics2D)g.create();layer.translate(mode==0?25:415,110);LaserEffect laser=new LaserEffect();laser.trail=mode==1;if(phase>=200){simulate(laser,phase);laser.render(phase,1,new Painter(layer));}layer.dispose();}g.dispose();return image;}
    static void visual(File directory)throws Exception{directory.mkdirs();for(int i=0;i<90;i++)ImageIO.write(frame(i*33L),"png",new File(directory,String.format("%03d.png",i)));ImageIO.write(frame(1450),"png",new File(directory.getParentFile(),"Folio-laser-preview.png"));}
    public static void main(String[] args)throws Exception{dot();pulse();trail();heldTrail();capacity();visual(new File(args[0]));System.out.println("PASS: "+assertions+" laser state and rendering assertions");}
}
